fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    debug_assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}

